import React, { useEffect, useState } from 'react';
import { itemsAPI, salesAPI, formatCurrency, formatDate } from '../api';

function Sales({ showToast }) {
  const [items, setItems] = useState([]);
  const [sales, setSales] = useState([]);
  const [loading, setLoading] = useState(true);
  const [formData, setFormData] = useState({
    itemId: '',
    quantitySold: '',
  });
  const [selectedItem, setSelectedItem] = useState(null);

  useEffect(() => {
    loadData();
  }, []);

  const loadData = async () => {
    try {
      setLoading(true);
      const [itemsData, salesData] = await Promise.all([
        itemsAPI.getAll(),
        salesAPI.getAll(),
      ]);
      setItems(itemsData.data || []);
      setSales(salesData.data || []);
    } catch (error) {
      showToast(`Failed to load data: ${error.message}`, 'error');
    } finally {
      setLoading(false);
    }
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    
    if (!formData.itemId) {
      showToast('Please select an item', 'error');
      return;
    }

    try {
      await salesAPI.create({
        itemId: formData.itemId,
        quantitySold: parseInt(formData.quantitySold),
      });
      showToast('Sale recorded successfully!');
      setFormData({ itemId: '', quantitySold: '' });
      setSelectedItem(null);
      loadData();
    } catch (error) {
      showToast(`Failed to record sale: ${error.message}`, 'error');
    }
  };

  const handleItemSelect = (e) => {
    const itemId = e.target.value;
    setFormData({ ...formData, itemId });
    const item = items.find((i) => i._id === itemId);
    setSelectedItem(item);
  };

  const calculateTotal = () => {
    if (!selectedItem || !formData.quantitySold) return 0;
    return selectedItem.price * parseInt(formData.quantitySold);
  };

  return (
    <div className="container">
      <div className="section-header">
        <h1 className="section-title">Sales Management</h1>
      </div>

      {/* Form */}
      <div className="form-card">
        <h2 className="form-title">💰 Record New Sale</h2>
        <form onSubmit={handleSubmit}>
          <div className="form-grid">
            <div className="form-group">
              <label className="form-label">Select Item *</label>
              <select
                className="form-select"
                value={formData.itemId}
                onChange={handleItemSelect}
                required
              >
                <option value="">-- Select Item --</option>
                {items.map((item) => (
                  <option key={item._id} value={item._id}>
                    {item.name} - {formatCurrency(item.price)} (Stock: {item.quantity})
                  </option>
                ))}
              </select>
            </div>

            <div className="form-group">
              <label className="form-label">Quantity *</label>
              <input
                type="number"
                className="form-input"
                value={formData.quantitySold}
                onChange={(e) =>
                  setFormData({ ...formData, quantitySold: e.target.value })
                }
                min="1"
                required
              />
            </div>
          </div>

          {selectedItem && formData.quantitySold && (
            <div
              style={{
                background: 'var(--light-gray)',
                padding: '1rem',
                borderRadius: '8px',
                marginTop: '1rem',
              }}
            >
              <p style={{ margin: '0.25rem 0' }}>
                <strong>Item:</strong> {selectedItem.name}
              </p>
              <p style={{ margin: '0.25rem 0' }}>
                <strong>Price per unit:</strong> {formatCurrency(selectedItem.price)}
              </p>
              <p style={{ margin: '0.25rem 0' }}>
                <strong>Quantity:</strong> {formData.quantitySold}
              </p>
              <p style={{ margin: '0.25rem 0', fontSize: '1.25rem', color: 'var(--primary)' }}>
                <strong>Total Amount:</strong> {formatCurrency(calculateTotal())}
              </p>
              {parseInt(formData.quantitySold) > selectedItem.quantity && (
                <p style={{ margin: '0.5rem 0 0', color: 'var(--danger)' }}>
                  ⚠️ Insufficient stock! Available: {selectedItem.quantity}
                </p>
              )}
            </div>
          )}

          <div className="form-actions">
            <button type="submit" className="btn btn-primary">
              💰 Record Sale
            </button>
            <button
              type="button"
              className="btn btn-secondary"
              onClick={() => {
                setFormData({ itemId: '', quantitySold: '' });
                setSelectedItem(null);
              }}
            >
              Clear
            </button>
          </div>
        </form>
      </div>

      {/* Sales History */}
      <div className="card">
        <h3 style={{ marginBottom: '1rem', fontSize: '1.25rem' }}>Recent Sales</h3>
        {loading ? (
          <div className="loading-container">
            <div className="loading-spinner"></div>
            <p className="loading-text">Loading sales...</p>
          </div>
        ) : sales.length === 0 ? (
          <div className="empty-state">
            <div className="empty-state-icon">💰</div>
            <h3 className="empty-state-title">No sales recorded yet</h3>
            <p className="empty-state-description">Record your first sale to get started!</p>
          </div>
        ) : (
          <div className="table-container">
            <table className="table">
              <thead>
                <tr>
                  <th>Date</th>
                  <th>Item</th>
                  <th>Quantity</th>
                  <th>Price/Unit</th>
                  <th>Total</th>
                </tr>
              </thead>
              <tbody>
                {sales.map((sale) => (
                  <tr key={sale._id}>
                    <td>{formatDate(sale.saleDate)}</td>
                    <td>{sale.itemName}</td>
                    <td>{sale.quantitySold}</td>
                    <td>{formatCurrency(sale.pricePerUnit)}</td>
                    <td>
                      <strong>{formatCurrency(sale.totalAmount)}</strong>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </div>
    </div>
  );
}

export default Sales;
